{
  "justification": "Issue salience clusters around living costs, immigration, and the general economy, with added concern for health and the environment. The electorate leans somewhat authoritarian (6.2/10), is slightly left-of-centre overall (4.74/10) and mildly Eurosceptic (4.73/10), pointing to strong authority and loyalty pulls alongside care and some egalitarian impulse, with little evidence for sanctity.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "High salience of living costs (19.7%), health (7.0%), environment (6.1%), poverty (1.3%), and inequality (1.1%).",
      "status": "SCORED",
      "weight": 0.35
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration salience (17.0%), defence/war (1.3%/2.0%), national identity (0.3%), and slightly lower European integration support (4.73/10).",
      "status": "SCORED",
      "weight": 0.2
    },
    {
      "foundation": "authority",
      "basis": "Derived authority–liberty scale mean 6.2/10 (more authoritarian), plus salience of crime (2.4%) and defence/terrorism (1.3%/0.3%).",
      "status": "SCORED",
      "weight": 0.3
    },
    {
      "foundation": "sanctity",
      "basis": "Very low salience of morals (0.3%) and gender/sexuality/family (0.1%) with no directional indicators.",
      "status": "INSUFFICIENT",
      "weight": null
    },
    {
      "foundation": "equality",
      "basis": "Slightly left self-placement (4.74/10) and salience of inequality/poverty/welfare/taxation alongside living costs.",
      "status": "SCORED",
      "weight": 0.15
    },
    {
      "foundation": "proportionality",
      "basis": "Economic and immigration concerns (economy-general, taxation, immigration) implicate deservingness/reciprocity but direction is not resolved by the data.",
      "status": "AMBIGUOUS",
      "weight": null
    }
  ]
}
